def allocate_rng(rng_name):
    # Load the GSL CBLAS library
    try:
        cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    except OSError:
        raise RuntimeError("Failed to load libgslcblas.so")

    # Load the GSL library
    try:
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError:
        raise RuntimeError("Failed to load libgsl.so")

    # Define the gsl_rng_type and gsl_rng structures
    class gsl_rng_type(ctypes.Structure):
        _fields_ = []

    class gsl_rng(ctypes.Structure):
        _fields_ = []

    # Define function signatures
    gsl.gsl_rng_alloc.argtypes = [ctypes.POINTER(gsl_rng_type)]
    gsl.gsl_rng_alloc.restype = ctypes.POINTER(gsl_rng)

    # Get the type of random number generator
    gsl.gsl_rng_type_name.argtypes = [ctypes.POINTER(gsl_rng_type)]
    gsl.gsl_rng_type_name.restype = ctypes.c_char_p

    # Find the RNG type by name
    rng_type = ctypes.pointer(gsl_rng_type())
    for i in range(gsl.gsl_rng_types_count()):
        type_ptr = gsl.gsl_rng_types[i]
        type_name = gsl.gsl_rng_type_name(type_ptr).decode('utf-8')
        if type_name == rng_name:
            rng_type = type_ptr
            break
    else:
        raise ValueError(f"Unknown RNG type: {rng_name}")

    # Allocate the RNG
    rng = gsl.gsl_rng_alloc(rng_type)
    if not rng:
        raise RuntimeError("Failed to allocate RNG")

    return rng

