        if not all(isinstance(x, (int, float)) for x in weights) or not all(isinstance(x, (int, float)) for x in data):
            raise TypeError("Weights and data must contain only numeric values.")

        if wstride <= 0 or stride <= 0:
            raise ValueError("Strides must be positive integers.")

        # Convert lists to arrays
        weight_array = (ctypes.c_double * len(weights))(*weights)
        data_array = (ctypes.c_double * len(data))(*data)

        # Define function signature
        gsl.gsl_stats_wmean.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t, ctypes.POINTER(ctypes.c_double), ctypes.c_size_t]
        gsl.gsl_stats_wmean.restype = ctypes.c_double

        # Call the C function
        result = gsl.gsl_stats_wmean(weight_array, len(weights), wstride, data_array, stride)
