import sys

class GslRstatQuantileWorkspace:
    def __init__(self, p):
        self.p = p
        self.workspace = None
        self.libgsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        self.libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

        # Define function signatures
        self.libgsl.gsl_rstat_quantile_alloc.argtypes = [ctypes.c_size_t]
        self.libgsl.gsl_rstat_quantile_alloc.restype = ctypes.c_void_p

        self.libgsl.gsl_rstat_quantile_reset.argtypes = [ctypes.c_void_p]
        self.libgsl.gsl_rstat_quantile_reset.restype = None

        self.libgsl.gsl_rstat_quantile_add.argtypes = [ctypes.c_void_p, ctypes.c_double]
        self.libgsl.gsl_rstat_quantile_add.restype = None

        self.libgsl.gsl_rstat_quantile_get.argtypes = [ctypes.c_void_p, ctypes.c_double]
        self.libgsl.gsl_rstat_quantile_get.restype = ctypes.c_double

        self.libgsl.gsl_rstat_quantile_free.argtypes = [ctypes.c_void_p]
        self.libgsl.gsl_rstat_quantile_free.restype = None

        # Allocate workspace
        self.workspace = self.libgsl.gsl_rstat_quantile_alloc(ctypes.c_size_t(1))
        if not self.workspace:
            raise RuntimeError("Failed to allocate quantile workspace")

    def reset(self):
        self.libgsl.gsl_rstat_quantile_reset(self.workspace)

    def add_value(self, value):
        self.libgsl.gsl_rstat_quantile_add(self.workspace, ctypes.c_double(value))

    def get_quantile(self):
        return self.libgsl.gsl_rstat_quantile_get(self.workspace, ctypes.c_double(self.p))

    def free(self):
        self.libgsl.gsl_rstat_quantile_free(self.workspace)

    def __del__(self):
        if self.workspace:
            self.free()

def compute_quantile(p, values):
    if not (0 <= p <= 1):
        raise ValueError("p must be between 0 and 1")

    if not values:
        raise ValueError("values list cannot be empty")

    workspace = GslRstatQuantileWorkspace(p)
    try:
        for value in values:
            workspace.add_value(value)
        return workspace.get_quantile()
    finally:
        workspace.free()

