    if len(sys.argv) < 3:
        print("Usage: python script.py <p> <value1> <value2> ...")
        sys.exit(1)

    try:
        p = float(sys.argv[1])
        values = list(map(float, sys.argv[2:]))
        result = compute_quantile(p, values)
        print(f"Quantile {p} of the values is: {result}")
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

